def candidate(kernel, vectors):
    length = kernel.shape[0]
    kernel_fft = jnp.fft.rfft(kernel)
    vectors_fft = jnp.fft.rfft(vectors, axis=-1)
    return jnp.fft.irfft(vectors_fft * kernel_fft, n=length, axis=-1)

